<?php if (!$appointments): ?><div class="empty-state"><i class="bi bi-calendar2" aria-hidden="true"></i><p>Bu seçim için randevu bulunmuyor.</p></div><?php else: ?>
<div class="table-responsive"><table class="table align-middle admin-table"><thead><tr><th>Tarih / saat</th><th>Müşteri</th><th>Çalışan / hizmet</th><th>Tutar</th><th>Durum</th><?php if($showActions ?? false): ?><th>İşlem</th><?php endif ?></tr></thead><tbody>
<?php foreach($appointments as $appointment): ?><tr><td><?= e(date('d.m.Y H:i',strtotime($appointment['start_at']))) ?><small><?= e(date('H:i',strtotime($appointment['end_at']))) ?> bitiş · #<?= (int)$appointment['id'] ?></small></td><td><?= e($appointment['customer_name']) ?></td><td><?= e($appointment['employee_name']) ?><small><?= e($appointment['service_name']) ?></small></td><td class="text-nowrap"><?= e($money($appointment['service_price'])) ?></td><td><span class="status-pill status-<?= e($appointment['status']) ?>"><?= e($statusLabels[$appointment['status']]) ?></span></td>
<?php if($showActions ?? false): ?><td><div class="d-flex flex-wrap gap-2"><?php foreach(match($appointment['status']){'pending'=>['confirmed','cancelled'],'confirmed'=>['completed','cancelled'],default=>[]} as $next): ?><form method="post" action="<?= e(url('admin/appointments/status')) ?>"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$appointment['id'] ?>"><input type="hidden" name="status" value="<?= e($next) ?>"><button type="submit" class="btn btn-sm <?= $next==='cancelled' ? 'btn-outline-danger' : 'btn-outline-dark' ?>" <?= $next==='completed' && strtotime($appointment['end_at'])>time() ? 'disabled title="Randevu bitişinden sonra tamamlanabilir"' : '' ?>><?= e(['confirmed'=>'Onayla','completed'=>'Tamamla','cancelled'=>'İptal et'][$next]) ?></button></form><?php endforeach ?></div></td><?php endif ?></tr><?php endforeach ?>
</tbody></table></div><?php endif ?>
